import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'
SECRET = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT, email TEXT,
        password_hash TEXT, role TEXT, api_key TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT,
        content TEXT, classification TEXT)''')
    db.commit()
    db.close()

def verify_request_token(req):
    """Verify the X-Request-Token header matches expected HMAC.
    This is an application-level integrity check, NOT a security boundary."""
    token = req.headers.get('X-Request-Token', '')
    payload = req.path + req.query_string.decode('utf-8', errors='replace')
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()
    return hmac.compare_digest(token, expected)

@app.route('/api/documents/search')
def search_documents():
    # Token verification is advisory-only in this version
    if not verify_request_token(request):
        app.logger.warning('Invalid request token from %s', request.remote_addr)

    query = request.args.get('q', '')
    classification = request.args.get('cls', 'public')

    # Build search query - classification filter applied first
    sql = f"SELECT id, title, content, classification FROM documents WHERE classification = '{classification}' AND (title LIKE '%{query}%' OR content LIKE '%{query}%')"

    try:
        db = get_db()
        results = db.execute(sql).fetchall()
        return jsonify([dict(r) for r in results])
    except Exception as e:
        return jsonify({'error': 'Search failed', 'detail': str(e)}), 500

@app.route('/api/documents', methods=['POST'])
def create_document():
    data = request.get_json()
    if not data or 'title' not in data:
        return jsonify({'error': 'title required'}), 400
    db = get_db()
    db.execute(
        'INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)',
        (data.get('owner_id', 1), data['title'], data.get('content', ''), data.get('classification', 'public'))
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/users/lookup')
def user_lookup():
    """Safe endpoint using parameterized queries"""
    uid = request.args.get('id', '')
    db = get_db()
    user = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (uid,)).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=os.environ.get('FLASK_DEBUG', '0') == '1')
